fragment.source:
vec3 ridgeHue(float z,vec3 ink){
 return ink*mix(1.0,.55,z);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=fragCoord/iResolution.xy;
 float aspect=iResolution.x/iResolution.y;
 float px=(uv.x-.5)*aspect,y=uv.y;
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float N=clamp(floor(uParam_lines+.5),10.0,36.0);
 float horizon=.80;
 float farBase=horizon-.84/4.2;
 vec2 lh=vec2((uParam_left_x-.5)*aspect,uParam_left_y),rh=vec2((uParam_right_x-.5)*aspect,uParam_right_y);
 // A visible hand leaves a small bump; raising it past the chest lifts the peak.
 float llift=uParam_lift*(.12*smoothstep(.02,.2,lh.y)+1.1*smoothstep(.35,.9,lh.y));
 float rlift=uParam_lift*(.12*smoothstep(.02,.2,rh.y)+1.1*smoothstep(.35,.9,rh.y));
 bool hands=llift+rlift>.001;
 float motion=clamp(uParam_motion,0.0,1.0);
 float lp=smoothstep(.02,.2,lh.y)*motion,rp=smoothstep(.02,.2,rh.y)*motion;
 bool ripples=lp+rp>.001;
 float env=.16+.84*exp(-px*px*1.8);
 // Highest lift any ridge can reach at this column (terrain <= 1.1, peak shape <= 1.3).
 float reach=uParam_height*1.3*env*1.1+.2*strike*env+.05*motion;
 float handReach=0.0;
 if(hands){float ul=abs(px-lh.x)/.17,ur=abs(px-rh.x)/.17;handReach=1.3*(llift*exp(-ul*sqrt(ul))+rlift*exp(-ur*sqrt(ur)));}
 reach+=handReach;
 float pix=1.0/iResolution.y;
 vec3 c=vec3(0.0);
 bool covered=false;
 // A ridge is skipped below when y-.82 > (reach*.56-.84)/D. Above the near
 // ridges that test holds for a run starting at the front, so the loop starts
 // past that run (one ridge early, to stay clear of rounding).
 float lowReach=reach*.56-.84,above=y-.82,first=0.0;
 if(lowReach<0.0)first=above>=0.0?36.0:max(floor((lowReach/above-1.0)*(N-1.0)/3.2-.01),0.0);
 // The coarse stage marks the ridges that can draw in this 4x4 block.
 vec4 reachable=vrchCoarseData(fragCoord);
 ivec2 reachBits=ivec2(reachable.xy+.5);
 first=max(first,reachable.z);
 for(int i=0;i<36;i++){
  float fi=float(i)+first;
  if(fi>=N)break;
  int ri=int(fi+.5);
  if(((ri<18?reachBits.x>>ri:reachBits.y>>(ri-18))&1)==0)continue;
  float z=fi/(N-1.0);
  float D=1.0+z*3.2;
  float base=horizon-.84/D;
  float scale=.56/D;
  // Above its highest possible crest and glow this ridge adds nothing.
  if(y>base+reach*scale+.02)continue;
  // Per-ridge values that do not depend on the pixel come from the frame stage.
  vec4 ridge=vrchFrameData(int(fi));
  float xw=px*D*.8,zw=z*4.2+t*.3;
  // Terrain, first stage: its dominant ridge term and slow swell bound the
  // height before the remaining terms, hand peak and ripple are evaluated.
  float xs=xw+.45*sin(zw*.7+xw*.37);
  float ta=1.0-abs(sin(xs*1.1+zw*.8+ridge.x));
  float ts=.5+.5*sin(xw*.62-zw*.47+t*.07);
  float nPart=ta*ta*.46+ts*.26;
  float nMax=nPart+.26+uParam_rough*.26;
  float fz=ridge.y;
  float hMax=uParam_height*1.3*env*pow(nMax,1.7)+handReach*fz*(.7+.6*nMax)+(.2*strike+.08*motion)*env;
  if(y>base+hMax*scale+.02)continue;
  float tb=1.0-abs(sin(xs*2.35-zw*1.05+t*.12+1.7));
  float tc=.5+.5*sin(xs*5.3+zw*2.3-t*.4);
  float n=nPart+tb*tb*.26+uParam_rough*tc*tc*.26;
  float h=uParam_height*1.3*env*pow(n,1.7);
  float peak=0.0;
  if(hands){
   float wide=.17/(1.0+z*1.2);
   float ul=abs(px-lh.x)/wide,ur=abs(px-rh.x)/wide;
   peak=(llift*exp(-ul*sqrt(ul))+rlift*exp(-ur*sqrt(ur)))*fz*(.7+.6*n);
  }
  float ripple=0.0;
  if(ripples){
   float rl=length(vec2(px-lh.x,(z-.2)*1.8)),rr=length(vec2(px-rh.x,(z-.2)*1.8));
   ripple=lp*sin(rl*26.0-t*7.0)*exp(-rl*3.5)+rp*sin(rr*26.0-t*7.0)*exp(-rr*3.5);
  }
  float wave=ridge.w;
  float lift=h+peak+(.10*wave+.04*ripple)*env;
  float d=y-(base+lift*scale);
  // Well above this crest the line and glow are negligible; skip their shading.
  if(d>.03)continue;
  float near=smoothstep(.03,.012,d);
  float fade=ridge.z;
  float w=(.55+.7*(1.0-z))*pix;
  float line=w*w/(d*d+w*w);
  float flow=.55+.45*sin(xw*1.4-t*.8+fi*1.7);
  float sg=max(sin(xw*5.0-t*2.3+fi*2.39),0.0),sg3=sg*sg*sg,sg6=sg3*sg3,sg12=sg6*sg6;
  float spark=uParam_glint>.01?uParam_glint*(sg12*sg12)*smoothstep(.15,.6,h+peak):0.0;
  float energy=(.26+.85*lift)*flow+spark*2.5+wave*1.4+peak*.35;
  vec3 hue=ridgeHue(z,uParam_color.rgb);
  hue*=.6+.4*smoothstep(.05,.7,lift);
  hue=mix(hue,vec3(1.0),clamp(peak*.1+spark*.45+wave*.25,0.0,.4));
  if(d<0.0){
   // Solid dark ridge face with a thin rim of light spilling below the crest.
   float rim=exp(d/(.004+.012*(1.0-z)));
   c+=hue*(rim*.12*(.4+lift)*flow+line*energy)*fade;
   covered=true;
   break;
  }
  float glow=exp(-d/(.004+.008*(1.0-z)))*.06*(.3+lift);
  c+=hue*(line*energy+glow)*fade*near;
 }
 if(!covered){
  vec2 cell=floor(vec2(px,y)*120.0);
  float r=fract(sin(dot(cell,vec2(12.9898,78.233)))*43758.5453);
  vec2 f=fract(vec2(px,y)*120.0)-.5;
  float star=step(.988,r)*exp(-dot(f,f)*18.0)*(.35+.65*sin(t*2.0+r*60.0)*.5+.5*uParam_glint)*smoothstep(farBase,farBase+.12,y);
  c+=uParam_color.rgb*star*.035;
  float g=max(y-farBase,0.0);
  c+=uParam_color.rgb*exp(-g*14.0)*.025*(.6+.4*exp(-px*px*.8));
 }
 c*=.55+uParam_light*1.1;
 fragColor=vec4(1.0-exp(-c),1.0);
}

frame.source:
// Texel i: ridge i's slow swell offset, hand-peak depth falloff, distance fade
// and accent wave, none of which depend on the pixel.
void vrchFrame(in int texel,out vec4 value){
 float N=clamp(floor(uParam_lines+.5),10.0,36.0);
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float z=float(texel)/(N-1.0);
 float zw=z*4.2+t*.3;
 float dz=(z-.2)/.2;
 float wz=(z-(1.0-strike))*6.0;
 value=vec4(1.5*sin(zw*.45+t*.04),exp(-dz*dz),mix(1.0,.12,pow(z,.7)),strike>0.0?strike*exp(-wz*wz):0.0);
}

coarse.source:
// Per 4x4 block: which ridges can draw anything in the block. The main pass skips a ridge at a
// pixel when the pixel is more than .03 above its crest; here each ridge's crest is bounded from
// above over the block's columns (exact terrain at the block centre plus its slope bound over half
// the block, hand peak and ripple at their maxima), so ridges skipped here are skipped there too.
// x: bits of ridges 0-17, y: bits 18-35 (built and read as integers so no GPU's
// approximate exp2 or division can flip a bit), z: first relevant ridge.
void vrchCoarse(in vec2 blockOrigin,in float blockSize,out vec4 value){
 float aspect=iResolution.x/iResolution.y;
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float N=clamp(floor(uParam_lines+.5),10.0,36.0);
 float horizon=.80;
 float x0=(blockOrigin.x+.5-.5*iResolution.x)/iResolution.y,x1=x0+(blockSize-1.0)/iResolution.y;
 float xc=.5*(x0+x1),hw=.5*(x1-x0);
 float y0=(blockOrigin.y+.5)/iResolution.y;
 vec2 lh=vec2((uParam_left_x-.5)*aspect,uParam_left_y),rh=vec2((uParam_right_x-.5)*aspect,uParam_right_y);
 float llift=uParam_lift*(.12*smoothstep(.02,.2,lh.y)+1.1*smoothstep(.35,.9,lh.y));
 float rlift=uParam_lift*(.12*smoothstep(.02,.2,rh.y)+1.1*smoothstep(.35,.9,rh.y));
 float motion=clamp(uParam_motion,0.0,1.0);
 float lp=smoothstep(.02,.2,lh.y)*motion,rp=smoothstep(.02,.2,rh.y)*motion;
 float pe=clamp(0.0,x0,x1);
 float envU=.16+.84*exp(-pe*pe*1.8);
 float hU=0.0;
 if(llift+rlift>.001){
  float ul=abs(clamp(lh.x,x0,x1)-lh.x)/.17,ur=abs(clamp(rh.x,x0,x1)-rh.x)/.17;
  hU=1.3*(llift*exp(-ul*sqrt(ul))+rlift*exp(-ur*sqrt(ur)));
 }
 // Slope bound of n per unit xw: dominant term 1.27, second 1.43, rough term 3.22 * rough.
 float slope=1.27+1.43+3.22*uParam_rough;
 int lo=0,hi=0;
 float first=N;
 for(int i=0;i<36;i++){
  float fi=float(i);
  if(fi>=N)break;
  float z=fi/(N-1.0);
  float D=1.0+z*3.2;
  float base=horizon-.84/D;
  float scale=.56/D;
  float zw=z*4.2+t*.3;
  float swell=1.5*sin(zw*.45+t*.04);
  float dz=(z-.2)/.2,fz=exp(-dz*dz);
  float wz=(z-(1.0-strike))*6.0,wave=strike>0.0?strike*exp(-wz*wz):0.0;
  float xw=xc*D*.8;
  float xs=xw+.45*sin(zw*.7+xw*.37);
  float ta=1.0-abs(sin(xs*1.1+zw*.8+swell));
  float ts=.5+.5*sin(xw*.62-zw*.47+t*.07);
  float tb=1.0-abs(sin(xs*2.35-zw*1.05+t*.12+1.7));
  float tc=.5+.5*sin(xs*5.3+zw*2.3-t*.4);
  float nU=ta*ta*.46+ts*.26+tb*tb*.26+uParam_rough*tc*tc*.26+slope*D*.8*hw+.003;
  float liftU=uParam_height*1.3*envU*pow(nU,1.7)+hU/1.3*fz*(.7+.6*nU)*1.3/1.3+(.10*wave+.04*(lp+rp))*envU;
  // hU already holds 1.3 x the hand lift; the main pass's peak is lift * falloff * fz * (.7+.6n).
  liftU=uParam_height*1.3*envU*pow(nU,1.7)+hU/1.3*fz*(.7+.6*nU)+(.10*wave+.04*(lp+rp))*envU;
  if(y0-(base+liftU*scale)<=.03+.005){
   first=min(first,fi);
   if(i<18)lo|=1<<i;else hi|=1<<(i-18);
  }
 }
 value=vec4(float(lo),float(hi),first,1.0);
}
